corrected_code:
import { authenticateWebSocketRequest } from "./session";
import { checkZoneAccess } from "./permissions";

const server = Bun.serve({
  port: 8080,
  async fetch(req, server) {
    const url = new URL(req.url);
    if (url.pathname === "/live-telemetry") {
      const zoneId = url.searchParams.get("zoneId");
      const user = authenticateWebSocketRequest(req);
      if (!user) return new Response("Unauthorized", { status: 401 });

      // Enforce zone authorization prior to upgrading HTTP connection to WebSocket
      const hasAccess = await checkZoneAccess(user.id, zoneId);
      if (!hasAccess) {
        return new Response("Forbidden: Access denied to zone", { status: 403 });
      }

      const upgraded = server.upgrade(req, {
        data: { userId: user.id, zoneId }
      });
      if (upgraded) return undefined;
      return new Response("Upgrade failed", { status: 400 });
    }
    return new Response("Not Found", { status: 404 });
  },
  websocket: {
    open(ws) {
      ws.subscribe(`hvac:zone:${ws.data.zoneId}`);
    },
    message(ws, message) {},
    close(ws) {
      ws.unsubscribe(`hvac:zone:${ws.data.zoneId}`);
    }
  }
});
